function mentorRequests(){return `${top('Mentorship requests','See project blockers and provide relevant human help. No session is assumed confirmed until accepted.',`<span class="pill pill-outline">${state.requests.length} requests · demo data</span>`,'MENTOR WORKSPACE')}<div class="twocol"><section class="card"><div class="card-head"><h3>Incoming requests</h3>${badge('Actionable','purple')}</div>${requestItems(state.requests.filter(x=>x.status==='pending'))}</section><section class="card"><div class="card-head"><h3>Accepted / closed requests</h3></div>${requestItems(state.requests.filter(x=>x.status!=='pending'))}<div class="info-box">Sessions need student consent and mentor availability. This prototype does not process real payments, issue meeting links or guarantee introductions.</div></section></div>`}
