 if(type==='evidence'){if(val.length<7){toast('Describe the evidence in at least a few words.');return}const m=p.milestones.find(x=>x.id===d.id);if(!m)return;m.evidence=short(val,300);m.status='reported';m.reviewedBy='';const uploaded=document.getElementById('modalEvidenceFile')?.files?.[0];if(uploaded){const ext=uploaded.name.split('.').pop().toLowerCase();if(uploaded.size>10*1024*1024||!['pdf','png','jpg','jpeg','webp','txt','docx'].includes(ext)){toast('Use PDF, image, DOCX or TXT under 10 MB.');return}const key=p.id+':'+m.id;const old=ATTACHMENTS.get(key);if(old)URL.revokeObjectURL(old.url);ATTACHMENTS.set(key,{name:uploaded.name,url:URL.createObjectURL(uploaded)});m.evidenceFileName=short(uploaded.name,120)}log(`${p.name} submitted evidence for ${m.title}`)}
