function csvExport(){const rows=[['Project','Team','Competition result','Composite progress','Verified milestones','Self-reported milestones','User validations','Mentor reviews','Status'],...state.projects.map(p=>[p.name,p.owner,p.award,progress(p).score,p.milestones.filter(m=>m.status==='verified').length,p.milestones.filter(m=>m.status==='reported').length,p.userTests,p.mentorReviews,continuationStatus(p).label])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='buildbeyond-demo-cohort.csv';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Sample cohort report exported. Contains synthetic data only.')}
